package expo.modules.recognitioncpu;
import java.nio.file.*;
import java.util.*;
import static expo.modules.recognitioncpu.CameraMatrixPlan.*;
import static expo.modules.recognitioncpu.CameraMatrixRecoveryPlan.*;
import static expo.modules.recognitioncpu.CameraMatrixRecoveryChecks.*;
/** Generated lifecycle proof boundaries. These do not claim Android recreated an Activity. */
public final class CameraMatrixFixtureLifecycleChecks {
  static final String A="44444444-4444-4444-4444-444444444444",B="55555555-5555-5555-5555-555555555555",C="66666666-6666-6666-6666-666666666666";
  static CameraMatrixFixtureLifecycle armed(Fixture f)throws Exception{f.store.selection();var life=f.store.fixtureLifecycle();life.claim(A,P1,101);return life;}
  static void recreated(CameraMatrixFixtureLifecycle life)throws Exception{ok(life.request(A,P1,101),"one request after stopped picker");life.invoked(A,P1,101);life.destroyed(A,P1,101);ok(life.created(B,A,P1,101,true),"new Activity in same process confirmed");}
  public static void main(String[] args)throws Exception{
    Path parent=Path.of(args[0]);Files.createDirectories(parent);
    Fixture good=new Fixture(parent,"good");var life=armed(good);no("intent cannot be claimed twice",()->life.claim(A,P1,101));ok(!life.request(B,P1,101),"new/non-origin instance cannot request");recreated(life);ok(!life.request(A,P1,101),"request cannot repeat");ok(!life.created(C,B,P1,101,true),"receipt never rewritten");no("same process cannot stand in for process death",()->life.requireDestinationProcess(P1,101));life.requireDestinationProcess(P2,202);ok(good.out.writes==0,"no lifecycle step writes output");good.restart();var restored=good.store.fixtureLifecycle();ok(!restored.request(A,P1,101),"restart cannot reconstruct recreation permit");restored.requireDestinationProcess(P2,202);good.store.destination(Lane.FIXTURE.uri,67,good.out.identity(),202);good.engine().continueSelected(good.out);good.store.fixtureLifecycle().requireSuccessfulFixture();ok(good.store.state().equals("TERMINAL"),"both independent lifecycle stages permit one fixture write");int writes=good.out.writes;good.restart();good.engine().continueSelected(good.out);ok(good.out.writes==writes,"completed fixture reopen read-only");
    Fixture lost=new Fixture(parent,"lost-permit");armed(lost);lost.restart();var lostLife=lost.store.fixtureLifecycle();ok(!lostLife.request(A,P1,101),"durable intent alone grants no recreation");ok(!lostLife.created(B,A,P2,202,true),"process recreation cannot fabricate Activity-only receipt");no("missing Activity receipt blocks callback",()->lostLife.requireDestinationProcess(P2,202));
    Fixture noDestroy=new Fixture(parent,"no-destroy");var nd=armed(noDestroy);nd.request(A,P1,101);nd.invoked(A,P1,101);ok(!nd.created(B,A,P1,101,true),"create alone is not destroy/create evidence");no("no destroy receipt",()->nd.requireDestinationProcess(P2,202));
    Fixture wrongProcess=new Fixture(parent,"wrong-process");var wp=armed(wrongProcess);wp.request(A,P1,101);wp.invoked(A,P1,101);wp.destroyed(A,P1,101);no("process death is not Activity recreation",()->wp.created(B,A,P2,202,true));no("wrong origin instance",()->wp.created(B,C,P1,101,true));no("missing registry-before-create",()->wp.created(B,A,P1,101,false));ok(!Files.exists(wrongProcess.root.resolve(CameraMatrixFixtureLifecycle.RECEIPT)),"bad evidence persists no receipt");
    Fixture oldPass=new Fixture(parent,"old-terminal-without-proof");oldPass.selected();oldPass.engine().continueSelected(oldPass.out);ok("READBACK_VERIFIED".equals(oldPass.store.payload("terminal").get("status")),"old terminal predicate alone would pass");no("new gate refuses old incomplete lifecycle predicate",()->oldPass.store.fixtureLifecycle().requireSuccessfulFixture());
    Fixture noDeath=new Fixture(parent,"no-death");var n=armed(noDeath);recreated(n);noDeath.store.destination(Lane.FIXTURE.uri,67,noDeath.out.identity(),101);noDeath.engine().continueSelected(noDeath.out);no("write without separate process change cannot satisfy actual gate",()->noDeath.store.fixtureLifecycle().requireSuccessfulFixture());
    Fixture torn=new Fixture(parent,"torn-intent");torn.store.selection();torn.io.partialBefore=CameraMatrixFixtureLifecycle.INTENT+".new";no("torn recreation intent",()->torn.store.fixtureLifecycle().claim(A,P1,101));torn.io.partialBefore="";no("torn intent preserved at reopen",()->torn.restart());ok(Files.exists(torn.root.resolve(CameraMatrixFixtureLifecycle.INTENT+".new")),"no reset of torn evidence");
    Fixture tornReceipt=new Fixture(parent,"torn-receipt");var tr=armed(tornReceipt);tr.request(A,P1,101);tr.invoked(A,P1,101);tr.destroyed(A,P1,101);tornReceipt.io.partialBefore=CameraMatrixFixtureLifecycle.RECEIPT+".new";no("torn lifecycle receipt",()->tr.created(B,A,P1,101,true));tornReceipt.io.partialBefore="";no("torn receipt cannot authorize callback after reopen",()->tornReceipt.restart());ok(Files.exists(tornReceipt.root.resolve(CameraMatrixFixtureLifecycle.RECEIPT+".new"))&&tornReceipt.out.writes==0,"torn receipt retained with no output");
    Fixture lock=new Fixture(parent,"no-lock");var l=armed(lock);lock.held=false;no("OS ownership required before request",()->l.request(A,P1,101));
    Path actual=parent.resolve(Lane.ACTUAL.root);Files.createDirectory(actual);Files.createFile(actual.resolve("lock"));Files.write(actual.resolve(CameraMatrixFixtureLifecycle.INTENT),new byte[]{1});no("actual root refuses fixture-only leaves",()->footprint(actual.toFile(),new IO(),Lane.ACTUAL));
    Path actualValid=parent.resolve("actual-valid").resolve(Lane.ACTUAL.root);Files.createDirectories(actualValid);Files.createFile(actualValid.resolve("lock"));var actualStore=new CameraMatrixRecoveryStore(actualValid.toFile(),new IO(),Lane.ACTUAL,()->{},SOURCE,APK,P1);actualStore.initialize(SOURCE,true);actualStore.selection();actualStore.destination(Lane.ACTUAL.uri,67,map("device","1","inode","2"),999);ok(!actualStore.payload("destination").containsKey("pid")&&actualStore.payload("destination").size()==6,"actual destination schema remains unchanged");no("actual store exposes no fixture lifecycle",()->actualStore.fixtureLifecycle());
    ok(FIXTURE_JOURNAL==18*1024&&FIXTURE_JOURNAL+FIXTURE_OUTPUT==22*1024&&22*1024<FIXTURE_ALLOWANCE,"expanded fixture evidence remains inside original64KiB");ok(ORIGINAL_CANONICAL+4096+JOURNAL==190*1024&&JOURNAL==14*1024,"actual bookkeeping bound unchanged");
    for(String leaf:FIXTURE_STEPS)ok(Files.size(good.root.resolve(leaf))<=RECORD,"lifecycle record <=2KiB");
    System.out.println("CameraMatrixFixtureLifecycleChecks assertions="+checks+"; generated only; actual Activity/process/grant proof pending phone verification");
  }
}
